 FROM Mob WHERE Mob_ID='100032783' AND PackageID='offline-killaloe-zone253';
INSERT OR REPLACE INTO Mob (ClassType, TranslationId, Name, Suffix, Guild, ExamineArticle, MessageArticle, Speed, Heading, Region, Model, Size, Strength, Constitution, Dexterity, Quickness, Intelligence, Piety, Empathy, Charisma, Level, Realm, EquipmentTemplateID, ItemsListTemplateID, NPCTemplateID, Race, Flags, AggroLevel, AggroRange, MeleeDamageType, RespawnInterval, FactionID, BodyType, HouseNumber, Brain, PathID, OwnerID, RoamingRange, IsCloakHoodUp, Gender, VisibleWeaponSlots, LastTimeRowUpdated, X, Y, Z, PackageID, Mob_ID)
 SELECT ClassType, TranslationId, Name, Suffix, Guild, ExamineArticle, MessageArticle, Speed, Heading, Region, Model, Size, Strength, Constitution, Dexterity, Quickness, Intelligence, Piety, Empathy, Charisma, Level, Realm, EquipmentTemplateID, ItemsListTemplateID, NPCTemplateID, Race, Flags, AggroLevel, AggroRange, MeleeDamageType, RespawnInterval, FactionID, BodyType, HouseNumber, Brain, PathID, OwnerID, RoamingRange, IsCloakHoodUp, Gender, VisibleWeaponSlots, LastTimeRowUpdated, 68803, 29644, 9564, 'offline-killaloe-zone253-extra', 'offline-killaloe-extra-002'
