-- Roaming: the pack roamed 120-250 units, so mobs looked parked. Wider ranges for both the pack and the extras.
UPDATE Mob SET RoamingRange=450 WHERE Region=253 AND PackageID IN ('offline-killaloe-zone253','offline-killaloe-zone253-extra')
   AND Name IN ('boogey spawn','forlorn spectre','clicking beetle','forest cat');
UPDATE Mob SET RoamingRange=300 WHERE Region=253 AND PackageID IN ('offline-killaloe-zone253','offline-killaloe-zone253-extra')
   AND Name='large rat';
